btn_part.onClick:
{{
  (() => {
    JSutils.resetInactivityTimer();
    const petID = appsmith.store.petSelecionado?.ani002_id;
    if (!petID) return showAlert('Selecione um pet primeiro!', 'warning');
    storeValue('petID_Particularidades', petID);
    navigateTo('020 - Tutores', {}, 'SAME_WINDOW');
  })()
}}

